function pctOfRegion(rows){
  // rows: [{region, amount}], grouped contiguously by region
  const out = [];
  let running = 0;
  let curRegion = null;
  for (const r of rows){
    if (r.region !== curRegion){ curRegion = r.region; running = 0; }
    running += r.amount;
    out.push({ region: r.region, amount: r.amount, pct: Math.round(100 * r.amount / running) });
  }
  return out;
}

